// Entrada: resposta do "Get Contato" (HubSpot GET). Saida: id, nome, wikiUrl.
const j = $json;
const p = j.properties || {};
const wikiUrl = p.palestrante_wiki_final_url || p.palestrante_wiki_url || '';
const nome = ((p.firstname || '') + ' ' + (p.lastname || '')).trim();
const macroTemaHub = p.macro_tema_contato || p.macro_tema || ''; // tema humano vindo do arquivo importado
return [{ json: { id: j.id, nome, wikiUrl, tema: p.tema || '', macroTemaHub } }];

// Entrada: resposta do "OpenAI". Saida: registro pronto pro Redis (chave + valor JSON).
const prep = $('Prepara Prompt').first().json;
let content = ($json.choices && $json.choices[0] && $json.choices[0].message)
  ? $json.choices[0].message.content
  : ($json.content || '{}');

let d;
try { d = typeof content === 'string' ? JSON.parse(content) : content; }
catch (e) { d = { macro_tema: '18. OUTROS', notas: {}, justificativas: {} }; }

const pesos = { quem_e: 3, defende: 5, entrega: 4, pra_quem: 5, comprova: 3, raiox: 4 };
const notasIn = d.notas || {};
const notas = {};
let total = 0;
for (const k of Object.keys(pesos)) {
  const n = Math.max(0, Math.min(5, Number(notasIn[k]) || 0));
  notas[k] = n;
  total += n * pesos[k];
}
const compat = Math.round((total / 120) * 100); // 120 = soma_pesos(24) * nota_max(5)

const rec = {
  id: prep.id,
  nome: prep.nome,
  macro_tema: prep.macroTemaHub || d.macro_tema || '18. OUTROS', // prioriza o tema humano do HubSpot
  notas,
  justificativas: d.justificativas || {},
  pontuacao_total: total,
  compatibilidade: compat,
  wiki_url: prep.wikiUrl,
  data_avaliacao: new Date().toISOString()
};

return [{ json: Object.assign({ redisKey: 'pcur:pal:' + prep.id, redisValue: JSON.stringify(rec) }, rec) }];
